// === Tab: mySketch ===
// Theme: Combining motion
// Compare sin / noise / random behavior

// テーマ : 動きを組み合わせる
// 回転＋揺れ、noise＋回転、sin＋randomなど動きが複雑になるとどう見えるか観察する。

let angle = 0;

function setup() {
	createCanvas(400, 400);
	textAlign(CENTER, CENTER);
}

function draw() {
	background(220);
	translate(200, 200);
	rotate(angle);
	stroke(0);

	//回転＋揺れ　sin (regular motion)
	let a = sin(frameCount * 0.1) * 100;
	fill(255);
	circle(50, a, 100);
	text("sin", 50, a);

	//noise＋回転　noise (smooth randomness)
	let b = noise(frameCount * 0.1) * 100;
	fill(0, 50);
	circle(50, b, 100);
	text("noise", 50, b);

	//sin + random (add jitter)
	let base = sin(frameCount * 0.1) * 100;
	// randomでブレを追加
	let r = random(-20, 20);
	// 合成
	let c = base + r;
	fill(255, 0, 0, 30);
	circle(50, c, 100);

	//noise振れ幅０～１　map (range conversion)
	let d = sin(frameCount * 0.1) * 100;
	fill(0, 255, 0, 50, 30);
	let e = map(d, -1, 1, 0, 1);
	circle(50, e, 100);

	angle += 0.01;
}

